-- Facturation : header document of a sale (a facture).
-- The reference is generated by the service (VTE-000001), the client is always
-- present (the system client "CLIENT COMPTANT" is used when none is selected),
-- the status is VALIDEE at creation and the total is recomputed from the lines.
CREATE TABLE `sales` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`reference` text NOT NULL,
	`client_id` integer NOT NULL,
	`sale_date` integer NOT NULL,
	`status` text NOT NULL,
	`total_amount` integer NOT NULL,
	`created_at` integer DEFAULT (cast((julianday('now') - 2440587.5)*86400000 as integer)) NOT NULL,
	`updated_at` integer DEFAULT (cast((julianday('now') - 2440587.5)*86400000 as integer)) NOT NULL,
	FOREIGN KEY (`client_id`) REFERENCES `clients`(`id`) ON UPDATE cascade ON DELETE restrict,
	CONSTRAINT "sales_status_check" CHECK("sales"."status" in ('VALIDEE', 'ANNULEE')),
	CONSTRAINT "sales_total_amount_check" CHECK("sales"."total_amount" >= 0)
);
