CREATE INDEX `sales_client_id_idx` ON `sales` (`client_id`);
--> statement-breakpoint
CREATE INDEX `sales_sale_date_idx` ON `sales` (`sale_date`);
--> statement-breakpoint
CREATE INDEX `sales_status_idx` ON `sales` (`status`);
