-- One line of a sale. `form` is the form really sold (a transformable product can
-- be sold in either of its two forms, with no automatic conversion) and
-- `unit_price` is the real price applied on this document: the price of the
-- product can change later without rewriting the history.
CREATE TABLE `sale_items` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`sale_id` integer NOT NULL,
	`product_id` integer NOT NULL,
	`form` text NOT NULL,
	`quantity` integer NOT NULL,
	`unit_price` integer NOT NULL,
	`line_total` integer NOT NULL,
	FOREIGN KEY (`sale_id`) REFERENCES `sales`(`id`) ON UPDATE cascade ON DELETE cascade,
	FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON UPDATE cascade ON DELETE restrict,
	CONSTRAINT "sale_items_quantity_check" CHECK("sale_items"."quantity" > 0),
	CONSTRAINT "sale_items_unit_price_check" CHECK("sale_items"."unit_price" >= 0),
	CONSTRAINT "sale_items_line_total_check" CHECK("sale_items"."line_total" >= 0)
);
--> statement-breakpoint
CREATE INDEX `sale_items_sale_id_idx` ON `sale_items` (`sale_id`);
--> statement-breakpoint
CREATE INDEX `sale_items_product_id_idx` ON `sale_items` (`product_id`);
--> statement-breakpoint
CREATE UNIQUE INDEX `sale_items_sale_product_form_unique` ON `sale_items` (`sale_id`,`product_id`,`form`);
